import{_ as d,C as i,o as l,c as t,ah as a,E as c}from"./chunks/framework.DuX8SFU5.js";const p=JSON.parse('{"title":"AM_NODE_V2 — руководство пользователя","description":"","frontmatter":{},"headers":[],"relativePath":"am_node_v2/user-guide.md","filePath":"am_node_v2/user-guide.md"}'),r={name:"am_node_v2/user-guide.md"};function n(s,e,_,A,h,m){const o=i("AssetImage");return l(),t("div",null,[e[0]||(e[0]=a('<h1 id="am-node-v2-—-руководство-пользователя" tabindex="-1">AM_NODE_V2 — руководство пользователя <a class="header-anchor" href="#am-node-v2-—-руководство-пользователя" aria-label="Permalink to &quot;AM_NODE_V2 — руководство пользователя&quot;">​</a></h1><p>Порядок ввода узла в работу: подключение, проверка, настройка и обновление прошивки. Характеристики, разъёмы и параметры прошивок — в <a href="./datasheet">даташите</a>.</p><h2 id="подключение" tabindex="-1">Подключение <a class="header-anchor" href="#подключение" aria-label="Permalink to &quot;Подключение&quot;">​</a></h2><p>Плату крепят, питают и включают в шину CAN по <a href="./datasheet#application">рекомендациям по применению</a>. Разъёмы и распиновка — в <a href="./datasheet#connectors">разделе 6 даташита</a>.</p><h2 id="проверка-при-вводе-в-эксплуатацию" tabindex="-1">Проверка при вводе в эксплуатацию <a class="header-anchor" href="#проверка-при-вводе-в-эксплуатацию" aria-label="Permalink to &quot;Проверка при вводе в эксплуатацию&quot;">​</a></h2><ul><li>Визуальная проверка: полярность XT30, USB-C, CAN, Ethernet, load и sensor connectors.</li><li>Без питания: проверить сопротивления между <code>Vin_in</code>, <code>5V</code>, <code>3V3</code> и <code>GND</code>.</li><li>Первое включение от лабораторного БП с ограничением тока: проверить 5 V и все 3.3 V rails.</li><li>Проверить масштабирование ADC входного напряжения и тока.</li><li>Для FMU mode: проверить CAN1/CAN2, RX/TX и конфигурацию терминаторов.</li><li>Для FMU mode: проверить USB enumeration через Type-C.</li><li>Для FMU mode: проверить доступ к LAN8742A по MDIO и PHY address.</li><li>Просканировать I2C и подтвердить адреса INA228 для <code>LOAD1</code>…<code>LOAD4</code> и <code>C_SENS1</code>…<code>C_SENS4</code>.</li><li>Проверить SPI-связь с MAX14906, <code>nREADY</code>, <code>nFAULT</code>, состояние концевиков и диагностику обрыва питания линий.</li><li>Проверить BYPASS для <code>LOAD1</code>…<code>LOAD4</code>, отдельно учесть общий BYPASS для <code>LOAD3</code>/<code>LOAD4</code>.</li><li>Протестировать каждый <code>LOADx</code>, <code>SENSx</code>, <code>C_SENSx</code> канал на токограниченной нагрузке до подключения финальных актуаторов.</li></ul><h2 id="настроика-узла" tabindex="-1">Настройка узла <a class="header-anchor" href="#настроика-узла" aria-label="Permalink to &quot;Настройка узла&quot;">​</a></h2><ol><li>Задать уникальный на шине <code>uavcan.node.id</code> и при необходимости имя узла <code>system.name</code>.</li><li>Настроить каналы LOAD, bypass и входы SENS по <a href="./datasheet#firmware">параметрам прошивки</a>, входы C_SENS — по <a href="./datasheet#ina228">настройке INA228</a>.</li><li>Сохранить параметры.</li></ol><p>Если на плату ставится прошивка с другим составом параметров, сохранённые значения читаются по новой таблице. Поэтому перед настройкой выполняют <strong>Erase All</strong>, затем задают параметры заново и сохраняют.</p><h2 id="обновление-прошивки" tabindex="-1">Обновление прошивки <a class="header-anchor" href="#обновление-прошивки" aria-label="Permalink to &quot;Обновление прошивки&quot;">​</a></h2>',10)),c(o,{name:"bootloader.gif",alt:"Обновление прошивки через bootloader"}),e[1]||(e[1]=a("<p>Прошивка обновляется через bootloader по CAN с помощью GUI-инструмента:</p><ol><li>Подключи плату к питанию и CAN-шине.</li><li>Открой GUI-инструмент и выбери нужный узел.</li><li>Выбери <code>.bin</code> файл прошивки.</li><li>Запусти обновление и дождись завершения загрузки.</li><li>После перезапуска проверь, что узел снова появился в сети.</li></ol><p>Если обновление не начинается, сначала проверь питание, CAN-H/CAN-L, общий GND, терминаторы и отсутствие конфликта <code>uavcan.node.id</code>.</p>",3))])}const N=d(r,[["render",n]]);export{p as __pageData,N as default};
